import { ChevronRight, Pause, Play, RotateCcw } from "lucide-react";
import { cn } from "@/lib/utils";

interface ControlsProps {
  currentPreset: string;
  generation: number;
  isPlaying: boolean;
  onPresetChange: (preset: string) => void;
  onReset: () => void;
  onSpeedChange: (speed: number) => void;
  onStep: () => void;
  onTogglePlay: () => void;
  presets: Record<string, { label: string }>;
  speed: number;
}

export function Controls({
  isPlaying,
  onTogglePlay,
  onStep,
  onReset,
  generation,
  speed,
  onSpeedChange,
  currentPreset,
  onPresetChange,
  presets,
}: ControlsProps) {
  return (
    <div className="absolute bottom-6 left-1/2 z-50 flex w-full max-w-3xl -translate-x-1/2 flex-col items-center gap-4 px-4 md:bottom-12 md:gap-6 md:px-6">
      {/* Preset Selector HUD */}
      <div className="flex flex-wrap justify-center gap-1.5 rounded-2xl border border-white/10 bg-white/5 p-1.5 shadow-[0_8px_32px_rgba(0,0,0,0.5)] backdrop-blur-xl md:gap-2">
        {Object.entries(presets).map(([id, preset]) => (
          <button
            className={cn(
              "rounded-xl px-3 py-2 font-bold text-[8px] uppercase tracking-widest transition-all duration-300 md:px-4 md:py-2 md:text-[10px] md:tracking-[0.2em]",
              currentPreset === id
                ? "bg-white text-black shadow-[0_0_20px_rgba(255,255,255,0.3)]"
                : "text-white/30 hover:bg-white/5 hover:text-white"
            )}
            key={id}
            onClick={() => onPresetChange(id)}
          >
            {preset.label}
          </button>
        ))}
      </div>

      {/* Main Control Hub */}
      <div className="flex w-full flex-col items-center gap-4 rounded-3xl border border-white/5 bg-black/40 px-6 py-4 shadow-2xl ring-1 ring-white/10 backdrop-blur-2xl md:w-auto md:flex-row md:gap-8 md:rounded-[2.5rem] md:px-10 md:py-5">
        {/* Stats & Actions Container for Mobile */}
        <div className="flex w-full items-center justify-between gap-4 md:w-auto md:gap-8">
          {/* Stats Section */}
          <div className="flex flex-col items-start border-white/10 md:border-r md:pr-8">
            <span className="mb-0.5 font-mono text-[8px] text-white/30 uppercase tracking-[0.2em] md:mb-1 md:text-[10px]">
              Iteration
            </span>
            <span className="font-black text-white text-xl tabular-nums tracking-tighter md:text-2xl">
              {generation.toLocaleString().padStart(4, "0")}
            </span>
          </div>

          {/* Action Buttons */}
          <div className="flex items-center gap-3 md:gap-5">
            <button
              className="group rounded-full p-2 text-white/40 transition-all hover:bg-white/10 hover:text-white md:p-3"
              onClick={onReset}
              title="Re-seed Simulation"
            >
              <RotateCcw className="h-4 w-4 transition-transform duration-500 group-hover:rotate-180 md:h-5 md:w-5" />
            </button>

            <button
              className={cn(
                "group relative rounded-full p-4 shadow-2xl transition-all duration-500 md:p-6",
                isPlaying
                  ? "scale-105 bg-white text-black"
                  : "bg-blue-600 text-white shadow-blue-500/20 hover:bg-blue-500"
              )}
              onClick={onTogglePlay}
            >
              {isPlaying ? (
                <Pause className="h-5 w-5 fill-current md:h-6 md:w-6" />
              ) : (
                <Play className="h-5 w-5 translate-x-0.5 fill-current md:h-6 md:w-6" />
              )}
            </button>

            <button
              className="rounded-full p-2 text-white/40 transition-all hover:bg-white/10 hover:text-white disabled:opacity-20 md:p-3"
              disabled={isPlaying}
              onClick={onStep}
              title="Step Forward"
            >
              <ChevronRight className="h-5 w-5 md:h-6 md:w-6" />
            </button>
          </div>
        </div>

        {/* Playback Settings */}
        <div className="flex w-full flex-col items-start border-white/10 md:min-w-[140px] md:border-l md:pl-8">
          <div className="mb-1.5 flex w-full justify-between text-[8px] md:mb-2 md:text-[10px]">
            <span className="font-mono text-white/30 uppercase tracking-[0.2em]">
              Interval
            </span>
            <span className="font-bold font-mono text-blue-400">{speed}ms</span>
          </div>
          <input
            className="h-1.5 w-full cursor-pointer appearance-none rounded-lg bg-white/10 accent-blue-500 opacity-80 transition-opacity hover:opacity-100 md:h-2"
            max="1000"
            min="20"
            onChange={(e) => onSpeedChange(Number.parseInt(e.target.value, 10))}
            step="20"
            type="range"
            value={speed}
          />
        </div>
      </div>
    </div>
  );
}

"use client";

import { Environment, OrbitControls, Stars } from "@react-three/drei";
import { Canvas } from "@react-three/fiber";
import {
  Bloom,
  ChromaticAberration,
  EffectComposer,
  Noise,
  Vignette,
} from "@react-three/postprocessing";
import React, { Suspense } from "react";
import * as THREE from "three";
import { Controls } from "./Controls";
import { PRESETS } from "./presets";
import { useLife3d } from "./useLife3d";
import { VoxelGrid } from "./VoxelGrid";

export default function Life_3d() {
  const [activePreset, setActivePreset] = React.useState("neural");

  const {
    grid,
    intensities,
    ages,
    dimensions,
    isPlaying,
    generation,
    speed,
    togglePlay,
    step,
    reset,
    setSpeed,
    updateRules,
  } = useLife3d({
    initialWidth: 40,
    initialHeight: 40,
    initialDepth: 40,
    initialDensity: PRESETS.neural.density,
    initialRules: PRESETS.neural.rules,
  });

  const handlePresetChange = (presetId: string) => {
    setActivePreset(presetId);
    const preset = PRESETS[presetId];
    updateRules(preset.rules);
    reset(
      dimensions.width,
      dimensions.height,
      dimensions.depth,
      preset.density,
      true
    );
  };

  return (
    <div className="group relative h-full w-full overflow-hidden bg-black">
      {/* R3F Canvas */}
      <Canvas camera={{ position: [35, 35, 35], fov: 45 }} dpr={[1, 2]} shadows>
        <OrbitControls
          autoRotate={!isPlaying}
          autoRotateSpeed={0.3}
          dampingFactor={0.05}
          enableDamping
          makeDefault
          maxDistance={100}
          minDistance={10}
        />

        <color args={["#010101"]} attach="background" />
        <fog args={["#010101", 50, 120]} attach="fog" />

        {/* Lighting - Brightened for better visibility */}
        <ambientLight intensity={0.8} />
        <pointLight color="#ffffff" intensity={3} position={[30, 40, 30]} />
        <spotLight
          angle={0.4}
          castShadow
          intensity={2.5}
          penumbra={1}
          position={[-30, 40, 30]}
        />

        <Environment preset="city" />

        {/* Simulation */}
        <Suspense fallback={null}>
          <VoxelGrid
            ages={ages}
            dimensions={dimensions}
            grid={grid}
            intensities={intensities}
          />
        </Suspense>

        <Stars
          count={8000}
          depth={70}
          factor={6}
          fade
          radius={150}
          saturation={0}
          speed={0.2}
        />

        {/* Post-Processing */}
        <EffectComposer multisampling={4}>
          <Bloom
            intensity={1.8}
            luminanceThreshold={0.15}
            mipmapBlur
            radius={0.5}
          />
          <Noise opacity={0.05} />
          <Vignette darkness={1.1} eskil={false} offset={0.05} />
          <ChromaticAberration
            modulationOffset={0}
            offset={new THREE.Vector2(0.004, 0.004)}
            radialModulation={false}
          />
        </EffectComposer>
      </Canvas>

      {/* Controls Overlay */}
      <Controls
        currentPreset={activePreset}
        generation={generation}
        isPlaying={isPlaying}
        onPresetChange={handlePresetChange}
        onReset={() => reset()}
        onSpeedChange={setSpeed}
        onStep={step}
        onTogglePlay={togglePlay}
        presets={PRESETS}
        speed={speed}
      />
    </div>
  );
}

import type { Life3dRules } from "./SimulationEngine";

export const PRESETS: Record<
  string,
  { label: string; rules: Life3dRules; density: number }
> = {
  neural: {
    label: "Neural Net",
    rules: { survival: [4, 5], birth: [5] }, // B5/S4,5
    density: 0.15,
  },
  amoeba: {
    label: "Organic Amoeba",
    rules: { survival: [5, 6, 7], birth: [6] }, // B6/S5,6,7
    density: 0.12,
  },
  fluid: {
    label: "Digital Fluid",
    rules: { survival: [2, 3], birth: [3] }, // B3/S2,3
    density: 0.08,
  },
  stable: {
    label: "Stable Islands",
    rules: { survival: [4, 5, 6, 7], birth: [4, 5] }, // B4,5/S4,5,6,7
    density: 0.18,
  },
};

import { useCallback, useEffect, useRef, useState } from "react";
import {
  type Grid,
  type Life3dRules,
  SimulationEngine,
} from "./SimulationEngine";

interface UseLife3dProps {
  initialDensity?: number;
  initialDepth?: number;
  initialHeight?: number;
  initialRules?: Life3dRules;
  initialWidth?: number;
}

export function useLife3d({
  initialWidth = 20,
  initialHeight = 20,
  initialDepth = 20,
  initialDensity = 0.12,
  initialRules = { survival: [4, 5], birth: [5] },
}: UseLife3dProps = {}) {
  const [grid, setGrid] = useState<Grid>(new Uint8Array(0));
  const [intensities, setIntensities] = useState<Float32Array>(
    new Float32Array(0)
  );
  const [ages, setAges] = useState<Uint16Array>(new Uint16Array(0));
  const [dimensions, setDimensions] = useState({
    width: initialWidth,
    height: initialHeight,
    depth: initialDepth,
  });
  const [isPlaying, setIsPlaying] = useState(false);
  const [speed, setSpeed] = useState(100);
  const [rules, setRules] = useState<Life3dRules>(initialRules);
  const [generation, setGeneration] = useState(0);

  const engineRef = useRef<SimulationEngine | null>(null);
  const timerRef = useRef<NodeJS.Timeout | null>(null);

  const reset = useCallback(
    (
      w = dimensions.width,
      h = dimensions.height,
      d = dimensions.depth,
      density = initialDensity,
      shouldPlay = false
    ) => {
      const engine = new SimulationEngine(w, h, d, rules);
      engine.seed(density);
      engineRef.current = engine;
      setGrid(new Uint8Array(engine.getGrid()));
      setIntensities(new Float32Array(engine.getIntensities()));
      setAges(new Uint16Array(engine.getAges()));
      setDimensions({ width: w, height: h, depth: d });
      setGeneration(0);
      setIsPlaying(shouldPlay);
    },
    [
      dimensions.width,
      dimensions.height,
      dimensions.depth,
      rules,
      initialDensity,
    ]
  );

  useEffect(() => {
    reset();
    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
  }, [reset]);

  const step = useCallback(() => {
    if (engineRef.current) {
      engineRef.current.step();
      setGrid(new Uint8Array(engineRef.current.getGrid()));
      setIntensities(new Float32Array(engineRef.current.getIntensities()));
      setAges(new Uint16Array(engineRef.current.getAges()));
      setGeneration((prev) => prev + 1);
    }
  }, []);

  useEffect(() => {
    if (isPlaying) {
      timerRef.current = setInterval(step, speed);
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
  }, [isPlaying, speed, step]);

  const togglePlay = () => setIsPlaying((prev) => !prev);

  const updateRules = (newRules: Life3dRules) => {
    setRules(newRules);
    if (engineRef.current) {
      engineRef.current.rules = newRules;
    }
  };

  return {
    grid,
    intensities,
    ages,
    dimensions,
    isPlaying,
    generation,
    speed,
    rules,
    togglePlay,
    step,
    reset,
    setSpeed,
    updateRules,
  };
}

import { useFrame } from "@react-three/fiber";
import { useEffect, useMemo, useRef } from "react";
import * as THREE from "three";

interface VoxelGridProps {
  ages: Uint16Array;
  dimensions: { width: number; height: number; depth: number };
  grid: Uint8Array;
  intensities: Float32Array;
}

export function VoxelGrid({
  grid,
  intensities,
  ages,
  dimensions,
}: VoxelGridProps) {
  const meshRef = useRef<THREE.InstancedMesh>(null);
  const { width, height, depth } = dimensions;
  const count = width * height * depth;

  const tempObject = useMemo(() => new THREE.Object3D(), []);
  const tempColor = useMemo(() => new THREE.Color(), []);

  // Update instances when grid changes
  useEffect(() => {
    if (!meshRef.current) {
      return;
    }

    let instanceIndex = 0;

    for (let z = 0; z < depth; z++) {
      for (let y = 0; y < height; y++) {
        for (let x = 0; x < width; x++) {
          const idx = x + y * width + z * width * height;
          const intensity = intensities[idx];

          if (intensity > 0.01) {
            const age = ages[idx];

            // Coordinate-based banding (Cyan/Pink/Yellow)
            const nx = x / width;
            const ny = y / height;

            // Bands:
            // - Top (ny > 0.8): Cream/Yellow
            // - Bottom Left (nx < 0.5): Magenta/Pink
            // - Bottom Right (nx >= 0.5): Cyan/Teal

            if (ny > 0.75) {
              tempColor.set("#fff176"); // Top: Pale Yellow
            } else if (nx < 0.5) {
              tempColor.set("#ff007f"); // Left: Hot Pink
            } else {
              tempColor.set("#00ffff"); // Right: Cyan
            }

            // Age highlights: Newborns are brighter/white
            if (age < 2) {
              tempColor.lerp(new THREE.Color("#ffffff"), 0.8);
            }

            // Persistence (Ghosting): Fade color to black based on intensity
            tempColor.multiplyScalar(intensity);

            tempObject.position.set(
              x - width / 2 + 0.5,
              y - height / 2 + 0.5,
              z - depth / 2 + 0.5
            );

            // Base scale is smaller for ghostly cells
            const baseScale = intensity * 0.45;
            tempObject.scale.setScalar(baseScale);
            tempObject.updateMatrix();

            meshRef.current.setMatrixAt(instanceIndex, tempObject.matrix);
            meshRef.current.setColorAt(instanceIndex, tempColor);

            instanceIndex++;
          }
        }
      }
    }

    // Hide remaining instances
    for (let i = instanceIndex; i < count; i++) {
      tempObject.position.set(0, 1000, 0); // Move out of view
      tempObject.scale.setScalar(0);
      tempObject.updateMatrix();
      meshRef.current.setMatrixAt(i, tempObject.matrix);
    }

    meshRef.current.instanceMatrix.needsUpdate = true;
    if (meshRef.current.instanceColor) {
      meshRef.current.instanceColor.needsUpdate = true;
    }
    meshRef.current.count = instanceIndex;
  }, [intensities, ages, width, height, depth, count, tempObject, tempColor]);

  // Pulsing animation
  useFrame((state) => {
    if (!meshRef.current) {
      return;
    }
    const t = state.clock.getElapsedTime();

    // Subtle breathing effect on the whole group
    meshRef.current.rotation.y = Math.sin(t * 0.1) * 0.05;
    meshRef.current.scale.setScalar(1 + Math.sin(t * 0.5) * 0.02);
  });

  return (
    <group>
      <instancedMesh args={[undefined, undefined, count]} ref={meshRef}>
        <icosahedronGeometry args={[0.5, 0]} />
        <meshStandardMaterial
          emissiveIntensity={4}
          metalness={1.0}
          roughness={0.05}
          toneMapped={false}
        />
      </instancedMesh>

      {/* Boundary Box - Sharp & Technical wireframe */}
      <mesh>
        <boxGeometry args={[width, height, depth]} />
        <meshBasicMaterial
          color="#ffffff"
          opacity={0.1}
          transparent
          wireframe
        />
      </mesh>
    </group>
  );
}

/**
 * 3D Game of Life Simulation Engine
 * Each cell has 26 neighbors in a 3x3x3 volume (excluding itself).
 */

export interface Life3dRules {
  birth: number[];
  survival: number[];
}

export type Grid = Uint8Array;
export type FloatGrid = Float32Array;

export class SimulationEngine {
  private readonly width: number;
  private readonly height: number;
  private readonly depth: number;
  private readonly size: number;
  public grid: Grid;
  private nextGrid: Grid;
  public intensities: FloatGrid;
  public ages: Uint16Array;
  public rules: Life3dRules;

  constructor(
    width: number,
    height: number,
    depth: number,
    rules?: Life3dRules
  ) {
    this.width = width;
    this.height = height;
    this.depth = depth;
    this.size = width * height * depth;
    this.grid = new Uint8Array(this.size);
    this.nextGrid = new Uint8Array(this.size);
    this.intensities = new Float32Array(this.size);
    this.ages = new Uint16Array(this.size);
    this.rules = rules || {
      survival: [4, 5],
      birth: [5],
    };
  }

  private getIndex(x: number, y: number, z: number): number {
    // Wrapping coordinates
    const wx = (x + this.width) % this.width;
    const wy = (y + this.height) % this.height;
    const wz = (z + this.depth) % this.depth;
    return wx + wy * this.width + wz * this.width * this.height;
  }

  public seed(density = 0.1) {
    for (let i = 0; i < this.size; i++) {
      const isAlive = Math.random() < density ? 1 : 0;
      this.grid[i] = isAlive;
      this.intensities[i] = isAlive ? 1.0 : 0.0;
      this.ages[i] = isAlive ? 1 : 0;
    }
  }

  public step(decay = 0.85) {
    for (let z = 0; z < this.depth; z++) {
      for (let y = 0; y < this.height; y++) {
        for (let x = 0; x < this.width; x++) {
          const neighbors = this.countNeighbors(x, y, z);
          const currentIdx = this.getIndex(x, y, z);
          const isAlive = this.grid[currentIdx] === 1;

          let willBeAlive = false;
          if (isAlive) {
            willBeAlive = this.rules.survival.includes(neighbors);
          } else {
            willBeAlive = this.rules.birth.includes(neighbors);
          }

          this.nextGrid[currentIdx] = willBeAlive ? 1 : 0;

          // Update intensity and age
          if (willBeAlive) {
            this.intensities[currentIdx] = 1.0;
            this.ages[currentIdx] = isAlive
              ? Math.min(this.ages[currentIdx] + 1, 65_535)
              : 1;
          } else {
            this.intensities[currentIdx] *= decay;
            if (this.intensities[currentIdx] < 0.01) {
              this.intensities[currentIdx] = 0;
              this.ages[currentIdx] = 0;
            }
          }
        }
      }
    }

    // Swap grids
    const temp = this.grid;
    this.grid = this.nextGrid;
    this.nextGrid = temp;
  }

  private countNeighbors(cx: number, cy: number, cz: number): number {
    let count = 0;
    for (let dz = -1; dz <= 1; dz++) {
      for (let dy = -1; dy <= 1; dy++) {
        for (let dx = -1; dx <= 1; dx++) {
          if (dx === 0 && dy === 0 && dz === 0) {
            continue;
          }
          if (this.grid[this.getIndex(cx + dx, cy + dy, cz + dz)] === 1) {
            count++;
          }
        }
      }
    }
    return count;
  }

  public getGrid(): Grid {
    return this.grid;
  }
  public getIntensities(): FloatGrid {
    return this.intensities;
  }
  public getAges(): Uint16Array {
    return this.ages;
  }
  public getDimensions() {
    return { width: this.width, height: this.height, depth: this.depth };
  }
}
